-- Запись журнала обновлений (ADR 0077): выпуск 86 — заявку своего сотрудника закрывают без объёма
-- работ, срочные перестали переставлять список, подсказок стало меньше, «Номенклатура» стала
-- «Расходниками» (ADR 0174, план `docs/office-equipment-card-and-list-cleanup-plan.md`, этапы
-- Э0–Э5 и обе фазы сервера).
--
-- ОТКУДА НОМЕР ФАЙЛА. `ls apps/api/drizzle` перед созданием (08.09.2026): 0286 — своя (индекс
-- срочности этой же волны), 0287 и 0288 занял соседний поток (виза площадки в механизации и
-- откат заказа ТС). Свободен 0289, он и взят.
--
-- `seq = 86`, И ЭТО ПЕРВЫЙ НЕЗАНЯТЫЙ. Номер спрошен у РЕПОЗИТОРИЯ
-- (`grep -h "^  [0-9]\+, '" apps/api/drizzle/*releases*.sql`), а не у базы: часть закоммиченных
-- выпусков на дев-базе не накатана, и `max(seq)` там врёт в меньшую сторону. Последняя строка
-- ленты — 85 (`0.1.74.0173`), отсюда версия `0.1.75.0174`: счётчик идёт дальше, хвост — номер
-- решения.
--
-- ЧТО ЭТА ЗАПИСЬ ОБЕЩАЕТ И ЧЕГО НЕ ОБЕЩАЕТ. Обещано: заявка, которую ведёт свой сотрудник,
-- закрывается датой и комментарием. Не обещано, что стоимость внутренних работ где-то появится, —
-- её не фиксируют нигде и не начинают; и не обещано, что исчезнут суммы у заявок сервисной
-- компании: там всё по-прежнему.
--
-- ОБРАТИМОСТЬ: строка ленты, `DELETE FROM app_releases WHERE seq = 86`.

INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  86, '0.1.75.0174', '2026-09-08', 'Оргтехника: свой ремонт закрывают без объёма работ', '{174}',
  '[
    {"kind":"feature","text":"Заявку, которую ведёт свой сотрудник, больше не заставляют составлять объём работ. Этапа нет вовсе: ни предъявления, ни согласования, вкладки «Объём работ» в карточке нет, а окно закрытия спрашивает дату выполнения и необязательное «что сделали». Прежде такая заявка не закрывалась вообще — закрытие требовало согласованной ревизии, и свой сисадмин выписывал смету сам себе, чтобы её подписал оператор"},
    {"kind":"feature","text":"У заявки сервисной компании всё по-прежнему: объём работ предъявляют, согласуют, закрывают по подписанной ревизии и подшивают акт. Правило одно — платят за работу снаружи или нет; смешанный состав «свой плюс подрядчик» считается подрядческим"},
    {"kind":"improvement","text":"Пометка «Рекомендована замена» и решение «что делаем вместо ремонта» переехали в окно отмены заявки. Раньше их ставили только отказом по объёму работ, которого у внутреннего ремонта больше не бывает: список «что пора менять» собирать стало бы нечем. При отмеченной замене решение обязательно; массовая отмена пометку не ставит"},
    {"kind":"improvement","text":"Срочные заявки больше не поднимаются в начало списка. Порядок задаёт та сортировка, которую выбрали: раньше выбор по номеру или дате начинал работать со второй строки. Срочность осталась — красная метка, поле карточки, пресет «Срочные» над таблицей, отбор в фильтрах и приставка «СРОЧНО» в теме письма"},
    {"kind":"improvement","text":"Пояснений в карточке и окнах стало меньше. Заявителю, исполнителю и представителю сервисной компании синие подсказки больше не показываются, а предупреждения свёрнуты в одну строку. Оператору и ИТ-службе всё осталось как было; причины, по которым кнопка не сработала, и ошибки видны всем полностью"},
    {"kind":"improvement","text":"Вкладка «Номенклатура» в карточке заявки на расходники называется «Расходники». Колонки «Сколько выдали» и «Причина расхождения» появляются с первой отметки о выдаче, а пустой состав объясняется словами вместо пустой таблицы. Код номенклатуры и справочник позиций остались прежними — переименована только вкладка заявки"}
  ]'::jsonb
);
